package com.nimbusbill.customer.entity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ai_recommendations") public class AiRecommendation{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="customer_id") private UUID customerId;@Column(nullable=false) private String category;@Column(nullable=false) private String title;@Column(nullable=false,columnDefinition="TEXT") private String rationale;@Column(name="recommended_action",nullable=false,columnDefinition="TEXT") private String recommendedAction;@Column(nullable=false) private String status="PENDING";@Column(name="created_by",nullable=false) private String createdBy;@Column(name="reviewed_by") private String reviewedBy;@Column(name="review_comment") private String reviewComment;@Column(name="created_at",nullable=false) private Instant createdAt;@Column(name="reviewed_at") private Instant reviewedAt;@PrePersist void create(){createdAt=Instant.now();}public UUID getId(){return id;}public UUID getCustomerId(){return customerId;}public void setCustomerId(UUID v){customerId=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getRationale(){return rationale;}public void setRationale(String v){rationale=v;}public String getRecommendedAction(){return recommendedAction;}public void setRecommendedAction(String v){recommendedAction=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getCreatedBy(){return createdBy;}public void setCreatedBy(String v){createdBy=v;}public String getReviewedBy(){return reviewedBy;}public void setReviewedBy(String v){reviewedBy=v;}public String getReviewComment(){return reviewComment;}public void setReviewComment(String v){reviewComment=v;}public Instant getCreatedAt(){return createdAt;}public Instant getReviewedAt(){return reviewedAt;}public void setReviewedAt(Instant v){reviewedAt=v;}}
